    /*
    DataContractAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(AVASalesQuotationRequestStatsReportQry)),
    SRSReportQueryAttribute(queryStr(AVASalesQuotationRequestStatsReportQry))
    */
    /*
