]
    public class AVASalesQuotationRequestStatsReportContract
{
    CreatedTransactionId        contractCreatedTransactionId;
//    RefRecId                    contractSalesQuotationTableRefRecId;
    QuotationIdBase             contractSalesQuotationId;
    smmBusRelAccount            contractSmmBusRelAccount;
